SELECT COUNT(order_id) AS canceled_orders_count
FROM orders
WHERE order_status = 'canceled';

SELECT COUNT(seller_id) AS seller_count
FROM sellers
WHERE seller_state = 'SP';

SELECT COUNT(DISTINCT product_category_name)
FROM products
WHERE product_category_name NOT IN (
  SELECT product_category_name_english
  FROM category_translation
);

SELECT payment_type, AVG(payment_installments) AS average_installments
FROM order_payments
GROUP BY payment_type;

SELECT COUNT(order_id) AS total_orders
FROM orders
WHERE order_status IN ('created', 'invoiced', 'processing', 'shipped', 'delivered');

SELECT AVG(order_delivered_customer_date - order_estimated_delivery_date) AS average_delay_days
FROM orders
WHERE order_status = 'delivered';

SELECT SUM(payment_value) AS total_payment_value
FROM order_payments
WHERE order_id = '0016dfedd97fc2950e388d2971d718c7';

SELECT COUNT(order_id) 
FROM orders 
WHERE order_delivered_customer_date IS NULL;

SELECT COUNT(*) 
FROM order_reviews 
WHERE review_comment_message IS NULL OR review_comment_message = '';

SELECT AVG(product_weight_g) AS average_product_weight
FROM products
WHERE product_weight_g IS NOT NULL;

SELECT COUNT(DISTINCT product_id)
FROM order_items
WHERE product_id NOT IN (SELECT product_id FROM products);

SELECT SUM(order_value) AS total_payment_value
FROM (
  SELECT order_id, SUM(price) AS order_value
  FROM order_items
  GROUP BY order_id
) AS order_values
WHERE order_id NOT IN (
  SELECT order_id
  FROM order_payments
);

SELECT AVG(geolocation_lat) AS average_latitude
FROM geolocation
WHERE geolocation_zip_code_prefix = '24220';
